mapper.update:
UPDATE generation_task SET execution_state = #{state}, error_code = #{errorCode},
    finished_at = #{now}, updated_at = #{now}, query_until = #{queryUntil}
WHERE request_id = #{requestId} AND execution_state = 'RUNNING'

mapper.select:
SELECT * FROM generation_task
WHERE app_id = #{appId} AND user_id = #{userId}
  AND (query_until IS NULL OR query_until > #{now})
AND request_id = #{requestId}
ORDER BY created_at DESC, request_id DESC LIMIT 1
